(()=>{const root=document.querySelector('.rf');if(!root)return;root.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.defaultPrevented)return;let u;try{u=new URL(a.href,location.href)}catch{return}if(/(?:^|\.)(?:amazon\.[a-z.]+|amzn\.to)$/.test(u.hostname)&&typeof window.gtag==='function')window.gtag('event','affiliate_click',{article_slug:root.dataset.articleSlug,product_name:a.dataset.affiliateProduct||a.textContent.trim(),link_placement:a.dataset.placement||'article',link_url:a.href,transport_type:'beacon'});});const count=root.querySelector('[data-check-count]');const checks=root.querySelectorAll('[data-checklist] input[type="checkbox"]');if(count&&checks.length){const update=()=>count.textContent=[...checks].filter(c=>c.checked).length+' of '+checks.length+' checks completed';checks.forEach(c=>c.addEventListener('change',update));update();}})();
